/**
 * Cron dispatch for `agent/schedules/`. In production mode a minute-aligned
 * ticker fires matching schedules (UTC evaluation); in dev mode nothing
 * fires automatically and `POST /v1/dev/schedules/:scheduleId` dispatches a
 * schedule by hand, exactly once, through the same path.
 */
import { parseCron } from "./cron.js";
import { SCHEDULE_CHANNEL_PREFIX } from "./session-engine.js";
export const APP_AUTH = {
    authenticator: "app",
    principalId: "agent-serve:app",
    principalType: "runtime",
};
export class UnknownScheduleError extends Error {
    constructor(scheduleId, availableScheduleIds) {
        super(`Unknown schedule "${scheduleId}"`);
        this.availableScheduleIds = availableScheduleIds;
        this.name = "UnknownScheduleError";
    }
}
export class ScheduleRunner {
    constructor(engine, project, logger = () => { }) {
        this.engine = engine;
        this.logger = logger;
        this.lastFiredMinute = -1;
        this.schedules = project.schedules.map((schedule) => ({
            name: schedule.name,
            cron: parseCron(schedule.cron),
            discovered: schedule,
        }));
    }
    get scheduleIds() {
        return this.schedules.map((schedule) => schedule.name);
    }
    start() {
        if (this.timer !== undefined || this.schedules.length === 0) {
            return;
        }
        this.arm();
    }
    stop() {
        if (this.timer !== undefined) {
            clearTimeout(this.timer);
            this.timer = undefined;
        }
    }
    arm() {
        const now = Date.now();
        const nextMinute = (Math.floor(now / 60_000) + 1) * 60_000;
        this.timer = setTimeout(() => this.tick(), nextMinute - now + 250);
        this.timer.unref?.();
    }
    tick() {
        const now = new Date();
        const minute = Math.floor(now.getTime() / 60_000);
        if (minute !== this.lastFiredMinute) {
            this.lastFiredMinute = minute;
            for (const schedule of this.schedules) {
                if (schedule.cron.matches(now)) {
                    void this.dispatch(schedule.name).catch((error) => {
                        this.logger(`[bdk] schedule "${schedule.name}" dispatch failed: ${error instanceof Error ? error.message : String(error)}`);
                    });
                }
            }
        }
        this.arm();
    }
    /**
     * Fire a schedule by name, exactly once. Returns the started sessions.
     *
     * `awaitCompletion` is the hosted v2 fire: the VM may be parked as soon as
     * the delivery replies, so resolve only after every started turn finished
     * and flushed to durable storage, and every `waitUntil` promise settled.
     * Without it the dispatch returns at message accept and work continues in
     * the background (the resident / local control plane path).
     */
    async dispatch(scheduleId, options = {}) {
        const schedule = this.schedules.find((s) => s.name === scheduleId);
        if (schedule === undefined) {
            throw new UnknownScheduleError(scheduleId, this.scheduleIds);
        }
        const definition = schedule.discovered.definition;
        const channelId = `${SCHEDULE_CHANNEL_PREFIX}${schedule.name}`;
        const awaitCompletion = options.awaitCompletion === true;
        if (definition.markdown !== undefined) {
            const { sessionId, done } = await this.engine.runTask({
                channelId,
                prompt: definition.markdown,
                auth: APP_AUTH,
                title: `Schedule ${schedule.name}`,
            });
            if (awaitCompletion) {
                await this.settleSession(sessionId, done);
            }
            else {
                this.engine.trackBackground(done);
            }
            return { sessionIds: [sessionId] };
        }
        if (definition.run === undefined) {
            throw new Error(`Schedule "${scheduleId}" has no markdown or run form`);
        }
        const sessionIds = [];
        const receivePromises = [];
        const waited = [];
        const receive = (channel, input) => {
            const promise = this.engine.receive(channel, input).then((session) => {
                sessionIds.push(session.id);
                return session;
            });
            receivePromises.push(promise.catch(() => { }));
            return promise;
        };
        await definition.run({
            receive,
            callTool: (toolName, input, callOptions) => this.engine.callTool(toolName, input, {
                auth: APP_AUTH,
                ...callOptions,
            }),
            waitUntil: (promise) => {
                this.engine.trackBackground(promise);
                if (awaitCompletion) {
                    waited.push(promise);
                }
            },
            appAuth: APP_AUTH,
            host: this.engine.host,
            artifacts: this.engine.artifacts,
        });
        // Collect ids from receive() calls the handler chose not to await
        // (commonly wrapped in waitUntil); receive resolves at message accept,
        // not turn completion, so this settles fast.
        await Promise.allSettled(receivePromises);
        if (awaitCompletion) {
            // waitUntil work may register more waitUntil work or call receive();
            // drain both until neither grows so every started turn is awaited.
            let settledWaited = 0;
            let settledReceives = 0;
            while (settledWaited < waited.length || settledReceives < receivePromises.length) {
                const batch = [...waited.slice(settledWaited), ...receivePromises.slice(settledReceives)];
                settledWaited = waited.length;
                settledReceives = receivePromises.length;
                await Promise.allSettled(batch);
            }
            await Promise.allSettled(sessionIds.map((sessionId) => this.settleSession(sessionId, this.engine.waitForCompletion(sessionId))));
        }
        return { sessionIds };
    }
    async settleSession(sessionId, done) {
        try {
            await done;
        }
        finally {
            await this.engine.drainSessionDurability(sessionId);
        }
    }
}
